# -*- coding: utf-8 -*-

"""
    Exceptions definitions for velocityclient.py
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"


class AuthenticationError(Exception):
    """
        Exception used when client fails to authenticate with Velocity server.
        Inherited from exception class.
    """

    pass


class FunctionConflict(Exception):
    """
        Exception used when client tries to add method with same name as alredy
        added one. Inherited from exception class.
    """

    pass

class PowerTestCasesMissing(Exception):
    """
        Exception used when client tries use ids of power test cases (power_on,
        power_off, power_reboot) which are missing in Velocity.
    """

    pass
